#include <bits/stdc++.h>
using namespace std;

int n;
string names[12];
long long Q[12], V[12], M[12], L[12];
long long capM = 20000000LL, capL = 25000000LL;
long long bestVal;
int bestSol[12], curSol[12];
int order[12];

double lpBound(int idx, long long rm, long long rl, long long curVal) {
    double ub = (double)curVal;
    for (int ii = idx; ii < n; ii++) {
        int i = order[ii];
        long long maxByM = (M[i] > 0) ? rm / M[i] : Q[i];
        long long maxByL = (L[i] > 0) ? rl / L[i] : Q[i];
        long long canTake = min({Q[i], maxByM, maxByL});
        if (canTake >= Q[i]) {
            ub += (double)V[i] * Q[i];
            rm -= M[i] * Q[i]; rl -= L[i] * Q[i];
        } else {
            double fM = (M[i] > 0) ? (double)rm / M[i] : 1e18;
            double fL = (L[i] > 0) ? (double)rl / L[i] : 1e18;
            double frac = min({(double)Q[i], fM, fL});
            if (frac > 0) ub += (double)V[i] * frac;
            break;
        }
    }
    return ub;
}

void solve(int idx, long long rm, long long rl, long long curVal) {
    if (curVal > bestVal) { bestVal = curVal; memcpy(bestSol, curSol, sizeof(bestSol)); }
    if (idx == n) return;
    if (lpBound(idx, rm, rl, curVal) <= (double)bestVal + 0.5) return;
    int i = order[idx];
    long long maxByM = (M[i] > 0) ? rm / M[i] : Q[i];
    long long maxByL = (L[i] > 0) ? rl / L[i] : Q[i];
    long long maxTake = min({Q[i], maxByM, maxByL});
    // Try max first, then binary-style: max, max-1, 0, and a few others
    set<long long> cands;
    cands.insert(maxTake);
    if(maxTake>0) cands.insert(maxTake-1);
    cands.insert(0);
    for (long long c : {maxTake/2, maxTake/3, maxTake*2/3, 1LL})
        if(c>=0 && c<=maxTake) cands.insert(c);
    // Actually just iterate if small enough
    if (maxTake <= 500) { cands.clear(); for(long long k=maxTake;k>=0;k--) cands.insert(k); }
    vector<long long> cv(cands.rbegin(), cands.rend());
    for (long long k : cv) {
        curSol[i] = (int)k;
        solve(idx+1, rm-k*M[i], rl-k*L[i], curVal+k*V[i]);
    }
    curSol[i] = 0;
}

int main(){
    string input((istreambuf_iterator<char>(cin)),{});
    vector<pair<string,vector<long long>>> entries;
    size_t pos=0;
    while(true){pos=input.find('"',pos);if(pos==string::npos)break;size_t end=input.find('"',pos+1);string key=input.substr(pos+1,end-pos-1);pos=end+1;size_t br=input.find('[',pos);if(br==string::npos)break;size_t br2=input.find(']',br);string arr=input.substr(br+1,br2-br-1);pos=br2+1;vector<long long>nums;stringstream ss(arr);string tok;while(getline(ss,tok,',')){long long v=0;bool neg=false;for(char c:tok){if(c=='-')neg=true;if(c>='0'&&c<='9')v=v*10+(c-'0');}if(neg)v=-v;nums.push_back(v);}if(nums.size()==4)entries.push_back({key,nums});}
    n=entries.size();
    for(int i=0;i<n;i++){names[i]=entries[i].first;Q[i]=entries[i].second[0];V[i]=entries[i].second[1];M[i]=entries[i].second[2];L[i]=entries[i].second[3];order[i]=i;}
    sort(order,order+n,[](int a,int b){double da=V[a]/max(M[a]*25.0+1e-30,L[a]*20.0+1e-30);double db=V[b]/max(M[b]*25.0+1e-30,L[b]*20.0+1e-30);return da>db;});
    bestVal=-1;memset(bestSol,0,sizeof(bestSol));memset(curSol,0,sizeof(curSol));
    solve(0,capM,capL,0);
    cout<<"{";
    for(int i=0;i<n;i++){if(i)cout<<", ";cout<<"\""<<names[i]<<"\": "<<bestSol[i];}
    cout<<"}"<<endl;
}
